1	package warranty
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	// 本文件回归保障同一承诺编号在首次成功预留前被两组不同内容并发抢占时，编号
11	// 只能绑定一份内容：两笔已登记、在保且不命中除外规则的请求，向同一备件提交
12	// 预留，数量与到期时刻各自合法，却共用同一个尚未成功预留的承诺编号，每组内容
13	// 都可能同时被提交多次。无论哪组先成功，与其完全相同的提交全部成功并返回同一
14	// 份完整的首次承诺，另一组提交全部 ErrConflict：不能两组都成功，也不能把后来
15	// 的内容写进已成功的承诺。库存只承担获胜内容一份占用（实物库存不变），承诺只
16	// 归属于获胜请求；历史上获胜请求只留一条首次成功记录（保存当次资格与新增占用
17	// 前的库存依据），落败请求每次提交各留一条冲突失败记录（数量、到期时刻与当前
18	// 时刻保留，资格与库存依据均为空），序号按实际处理次序递增。这些测试只沿用
19	// 登记、资格、预留与查询的既有公开行为。
20	
21	// concurrentReserveCall 是一次并发预留提交的入参。
22	type concurrentReserveCall struct {
23		commitID  string
24		requestID string
25		partID    string
26		quantity  int
27		expiry    time.Time
28		now       time.Time
29	}
30	
31	// concurrentReserveResult 是一次并发预留提交的结果。
32	type concurrentReserveResult struct {
33		commitment Commitment
34		err        error
35	}
36	
37	// reserveContent 是一组相同预留提交的内容（当前时刻不属于提交内容）。
38	type reserveContent struct {
39		requestID string
40		quantity  int
41		expiry    time.Time
42	}
43	
44	// fanOutConcurrentReserve 让全部调用在同一道闸机释放后同时进入 Reserve，尽量
45	// 制造交叉；返回与调用一一对应的结果，调用方按下标分组核对首次承诺与冲突。
46	func fanOutConcurrentReserve(s *Store, calls []concurrentReserveCall) []concurrentReserveResult {
47		results := make([]concurrentReserveResult, len(calls))
48		var wg sync.WaitGroup
49		start := make(chan struct{})
50		for i, c := range calls {
51			wg.Add(1)
52			go func(i int, c concurrentReserveCall) {
53				defer wg.Done()
54				<-start
55				results[i].commitment, results[i].err =
56					s.Reserve(c.commitID, c.requestID, c.partID, c.quantity, c.expiry, c.now)
57			}(i, c)
58		}
59		close(start)
60		wg.Wait()
61		return results
62	}
63	
64	// reserveContentionStore 构造同一产品下两笔在保、不命中除外规则的请求，以及
65	// 一个指定初始实物库存的备件；两者共用备件 part1。
66	func reserveContentionStore(t *testing.T, initialStock int) *Store {
67		t.Helper()
68		s := NewStore()
69		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
70			t.Fatalf("register product: %v", err)
71		}
72		if err := s.RegisterPart("part1", initialStock); err != nil {
73			t.Fatalf("register part: %v", err)
74		}
75		for _, id := range []string{"r1", "r2"} {
76			if err := s.SubmitRequest(id, "p1", "FAULTY"); err != nil {
77				t.Fatalf("submit request %s: %v", id, err)
78			}
79		}
80		return s
81	}
82	
83	// contentionCalls 构造两组各 n 个并发预留调用，交替排列以尽量交叉。两组使用
84	// 同一承诺编号与同一备件，仅请求、数量与到期时刻（即提交内容）不同；每个调用
85	// 给一个互不相同且都在保修期内、早于两笔到期时刻的当前时刻，便于核对落败记录
86	// 逐次保留当次当前时刻。
87	func contentionCalls(commitID, partID string, a, b reserveContent, n int) []concurrentReserveCall {
88		calls := make([]concurrentReserveCall, 0, 2*n)
89		for i := 0; i < n; i++ {
90			calls = append(calls, concurrentReserveCall{
91				commitID:  commitID,
92				requestID: a.requestID,
93				partID:    partID,
94				quantity:  a.quantity,
95				expiry:    a.expiry,
96				now:       nowOK.Add(time.Duration(i) * time.Minute),
97			})
98			calls = append(calls, concurrentReserveCall{
99				commitID:  commitID,
100				requestID: b.requestID,
101				partID:    partID,
102				quantity:  b.quantity,
103				expiry:    b.expiry,
104				now:       nowOK.Add(time.Duration(n+i) * time.Minute),
105			})
106		}
107		return calls
108	}
109	
110	// contentMatches 判断某次调用是否与指定内容一致（到期时刻按实际时刻比较）。
111	func contentMatches(c concurrentReserveCall, ct reserveContent) bool {
112		return c.requestID == ct.requestID && c.quantity == ct.quantity && c.expiry.Equal(ct.expiry)
113	}
114	
115	// assertReserveContentionSingleWinner 核对两组不同内容并发抢占同一承诺编号后的
116	// 全部不变量，并在争用结束后再次按两组内容各提交两次：获胜内容继续取回首次
117	// 承诺且不追加历史，落败内容继续冲突且每次各追加一条同样规则的冲突记录，库存
118	// 与归属保持争用结束时的结果。physical 是备件始终不变的实物库存。
119	func assertReserveContentionSingleWinner(t *testing.T, s *Store, commitID string,
120		calls []concurrentReserveCall, results []concurrentReserveResult, physical int, a, b reserveContent) {
121		t.Helper()
122		// 每组数量由调用长度推导。
123		groupN := len(calls) / 2
124		st, err := s.PartStatus("part1", nowOK)
125		if err != nil {
126			t.Fatalf("part status: %v", err)
127		}
128		if len(st.Details) != 1 {
129			t.Fatalf("details = %d, want exactly 1 commitment", len(st.Details))
130		}
131		d := st.Details[0]
132		var win, lose reserveContent
133		switch d.RequestID {
134		case a.requestID:
135			win, lose = a, b
136		case b.requestID:
137			win, lose = b, a
138		default:
139			t.Fatalf("winning detail request = %q, want %q or %q", d.RequestID, a.requestID, b.requestID)
140		}
141		wantFirst := Commitment{
142			ID:        commitID,
143			RequestID: win.requestID,
144			PartID:    "part1",
145			Quantity:  win.quantity,
146			Expiry:    win.expiry,
147		}
148	
149		// 明细字段与成功内容一致：原定数量、到期时刻对应胜者，已用为零、状态有效。
150		if d.CommitmentID != commitID || d.PartID != "part1" ||
151			d.OriginalQuantity != win.quantity || d.UsedQuantity != 0 ||
152			d.RemainingQuantity != win.quantity || !d.Expiry.Equal(win.expiry) ||
153			d.Status != CommitmentActive {
154			t.Fatalf("winning detail = %+v, want %+v active/used=0", d, wantFirst)
155		}
156		// 实物库存不被预留扣减；有效占用只对应获胜数量，即使库存充足到能容纳两笔。
157		if st.PhysicalRemaining != physical || st.ActiveOccupied != win.quantity ||
158			st.Committable != physical-win.quantity {
159			t.Fatalf("stock = %+v, want phys=%d occupied=%d committable=%d (winner=%s)",
160				st, physical, win.quantity, physical-win.quantity, win.requestID)
161		}
162		// 活动承诺与首次承诺快照内容一致，已用为零、未取消、未到期。
163		cur, err := s.Commitment(commitID)
164		if err != nil {
165			t.Fatalf("commitment: %v", err)
166		}
167		if cur != wantFirst {
168			t.Fatalf("stored commitment = %+v, want %+v", cur, wantFirst)
169		}
170	
171		// 按请求查看：承诺只归获胜请求，落败请求没有任何关联承诺。
172		winView, err := s.RequestView(win.requestID, nowOK)
173		if err != nil {
174			t.Fatalf("winner view: %v", err)
175		}
176		if len(winView.Commitments) != 1 || winView.Commitments[0].CommitmentID != commitID {
177			t.Fatalf("winner view commitments = %+v, want only %q", winView.Commitments, commitID)
178		}
179		loseView, err := s.RequestView(lose.requestID, nowOK)
180		if err != nil {
181			t.Fatalf("loser view: %v", err)
182		}
183		if len(loseView.Commitments) != 0 {
184			t.Fatalf("loser view commitments = %+v, want none", loseView.Commitments)
185		}
186	
187		// 逐调用核对：与获胜内容相同的全部成功并返回同一份完整首次承诺；落败内容
188		// 全部 ErrConflict 且返回空承诺。即使获胜后可承诺量已为零，同内容的其余
189		// 并发提交也取回首次结果，不得报库存不足。
190		winnerNows := make(map[time.Time]struct{}, groupN)
191		loserNows := make(map[time.Time]struct{}, groupN)
192		success, conflict := 0, 0
193		for i, c := range calls {
194			r := results[i]
195			if contentMatches(c, win) {
196				winnerNows[c.now] = struct{}{}
197				if r.err != nil || r.commitment != wantFirst {
198					t.Fatalf("winner-group call %d = %+v, err %v; want first %+v",
199						i, r.commitment, r.err, wantFirst)
200				}
201				if r.commitment.Used != 0 || r.commitment.Canceled || r.commitment.Expired {
202					t.Fatalf("winner-group call %d returned non-first state: %+v", i, r.commitment)
203				}
204				success++
205			} else if contentMatches(c, lose) {
206				loserNows[c.now] = struct{}{}
207				// 落败只可能是编号冲突：不能报库存不足等其他错误，也不能落库。
208				if !errors.Is(r.err, ErrConflict) || r.commitment != (Commitment{}) {
209					t.Fatalf("loser-group call %d = %+v, err %v; want ErrConflict with empty result",
210						i, r.commitment, r.err)
211				}
212				conflict++
213			} else {
214				t.Fatalf("call %d matches neither content: %+v", i, c)
215			}
216		}
217		if success != groupN || conflict != groupN {
218			t.Fatalf("success=%d conflict=%d, want exactly %d/%d", success, conflict, groupN, groupN)
219		}
220	
221		// 获胜请求只留一条首次成功记录；其余相同内容的成功返回不追加。
222		winHist, err := s.RequestHistory(win.requestID)
223		if err != nil {
224			t.Fatalf("winner history: %v", err)
225		}
226		if len(winHist) != 1 {
227			t.Fatalf("winner history len = %d, want 1", len(winHist))
228		}
229		wr := winHist[0]
230		if wr.Seq != 1 || !wr.Success || wr.Error != "" ||
231			wr.CommitID != commitID || wr.PartID != "part1" ||
232			wr.Quantity != win.quantity || !wr.Expiry.Equal(win.expiry) {
233			t.Fatalf("winner success record = %+v", wr)
234		}
235		if _, ok := winnerNows[wr.Now]; !ok {
236			t.Fatalf("winner record now %v not among winning submissions %v", wr.Now, winnerNows)
237		}
238		// 成功记录保存当次资格依据：请求合格、不命中除外。
239		if wr.Eligibility == nil || !wr.Eligibility.Eligible || wr.Eligibility.Excluded ||
240			wr.Eligibility.RequestID != win.requestID || len(wr.Eligibility.Reasons) != 0 {
241			t.Fatalf("winner eligibility snapshot = %+v", wr.Eligibility)
242		}
243		// 成功记录保存新增占用前的库存依据：实物 %d、占用 0、可承诺 %d。
244		if wr.StockBasis == nil ||
245			wr.StockBasis.PhysicalRemaining != physical || wr.StockBasis.ActiveOccupied != 0 ||
246			wr.StockBasis.Committable != physical {
247			t.Fatalf("winner stock basis = %+v, want phys=%d occupied=0 committable=%d",
248				wr.StockBasis, physical, physical)
249		}
250	
251		// 落败请求每次提交各留一条冲突失败记录，序号按处理次序连续递增，不挂到
252		// 获胜请求下；数量、到期时刻与当前时刻逐次保留，资格与库存依据均为空。
253		loseHist, err := s.RequestHistory(lose.requestID)
254		if err != nil {
255			t.Fatalf("loser history: %v", err)
256		}
257		if len(loseHist) != groupN {
258			t.Fatalf("loser history len = %d, want %d (one conflict per submission)", len(loseHist), groupN)
259		}
260		seenNows := make(map[time.Time]struct{}, groupN)
261		for i, rec := range loseHist {
262			if rec.Seq != i+1 || rec.Success || rec.Error != HistoryErrorConflict {
263				t.Fatalf("loser record %d = %+v, want seq=%d conflict failure", i, rec, i+1)
264			}
265			if rec.CommitID != commitID || rec.PartID != "part1" ||
266				rec.Quantity != lose.quantity || !rec.Expiry.Equal(lose.expiry) {
267				t.Fatalf("loser record %d submission fields = %+v", i, rec)
268			}
269			if _, ok := loserNows[rec.Now]; !ok {
270				t.Fatalf("loser record %d now %v not among losing submissions", i, rec.Now)
271			}
272			if _, dup := seenNows[rec.Now]; dup {
273				t.Fatalf("loser record %d duplicated now %v", i, rec.Now)
274			}
275			seenNows[rec.Now] = struct{}{}
276			if rec.Eligibility != nil || rec.StockBasis != nil {
277				t.Fatalf("loser record %d basis must be nil: elig=%+v stock=%+v",
278					i, rec.Eligibility, rec.StockBasis)
279			}
280		}
281	
282		// 争用结束后：获胜内容再次提交继续返回首次承诺（即使此刻可承诺量为零也
283		// 不报库存不足），不追加历史；落败内容再次提交仍冲突，每次各追加一条同样
284		// 规则的冲突记录；库存与归属保持原结果。
285		for k := 0; k < 2; k++ {
286			postNow := nowOK.Add(time.Duration(2*groupN+k) * time.Hour)
287			again, err := s.Reserve(commitID, win.requestID, "part1", win.quantity, win.expiry, postNow)
288			if err != nil || again != wantFirst {
289				t.Fatalf("post-hoc winner submit %d = %+v, err %v; want first %+v",
290					k, again, err, wantFirst)
291			}
292			h, _ := s.RequestHistory(win.requestID)
293			if len(h) != 1 {
294				t.Fatalf("post-hoc winner submit %d appended history: len=%d", k, len(h))
295			}
296	
297			loseNow := postNow.Add(30 * time.Minute)
298			got, err := s.Reserve(commitID, lose.requestID, "part1", lose.quantity, lose.expiry, loseNow)
299			if !errors.Is(err, ErrConflict) || got != (Commitment{}) {
300				t.Fatalf("post-hoc loser submit %d = %+v, err %v; want ErrConflict", k, got, err)
301			}
302			lh, _ := s.RequestHistory(lose.requestID)
303			wantLen := groupN + k + 1
304			if len(lh) != wantLen {
305				t.Fatalf("post-hoc loser history len = %d, want %d", len(lh), wantLen)
306			}
307			lr := lh[wantLen-1]
308			if lr.Seq != wantLen || lr.Success || lr.Error != HistoryErrorConflict ||
309				lr.Quantity != lose.quantity || !lr.Expiry.Equal(lose.expiry) ||
310				!lr.Now.Equal(loseNow) || lr.Eligibility != nil || lr.StockBasis != nil {
311				t.Fatalf("post-hoc loser record = %+v, want seq=%d conflict with nil basis", lr, wantLen)
312			}
313		}
314	
315		// 赛后库存与归属不变。
316		final, _ := s.PartStatus("part1", nowOK)
317		if final.PhysicalRemaining != physical || final.ActiveOccupied != win.quantity ||
318			final.Committable != physical-win.quantity || len(final.Details) != 1 ||
319			final.Details[0].RequestID != win.requestID {
320			t.Fatalf("post-hoc state changed: %+v", final)
321		}
322		cur2, _ := s.Commitment(commitID)
323		if cur2 != wantFirst {
324			t.Fatalf("post-hoc commitment changed: %+v, want %+v", cur2, wantFirst)
325		}
326	}
327	
328	// TestConcurrentReserveSameIDDifferentContentSingleWinner 对应用户给出的主例：
329	// 初始实物库存十件，两笔在保、不命中除外的请求分别要三件和四件（到期时刻也
330	// 不同），各组同时多次提交同一个尚未成功预留的承诺编号。只能有一份内容成为
331	// 首次承诺：同内容提交全部成功并返回同一份承诺，另一笔全部 ErrConflict；处理
332	// 完实物仍为十件，有效占用与可承诺量只对应获胜数量，承诺与历史只归获胜请求。
333	func TestConcurrentReserveSameIDDifferentContentSingleWinner(t *testing.T) {
334		const commitID = "cX"
335		contentA := reserveContent{requestID: "r1", quantity: 3, expiry: expiryOK}
336		contentB := reserveContent{requestID: "r2", quantity: 4, expiry: expiryOK.Add(10 * day)}
337	
338		const n = 12
339		for iter := 0; iter < 5; iter++ {
340			t.Run("iteration", func(t *testing.T) {
341				s := reserveContentionStore(t, 10)
342				calls := contentionCalls(commitID, "part1", contentA, contentB, n)
343				results := fanOutConcurrentReserve(s, calls)
344				assertReserveContentionSingleWinner(t, s, commitID, calls, results, 10, contentA, contentB)
345			})
346		}
347	}
348	
349	// TestConcurrentReserveSameIDExactStockWinnerTakesAll 保障库存恰好被首次成功
350	// 预留用完的情况：初始库存五件，两笔请求各要五件（仅请求不同）。同内容的其余
351	// 提交仍取回首次结果，不得因可承诺量归零而报库存不足；另一笔仍报编号冲突而非
352	// 库存不足。赛后获胜内容再次提交继续返回首次承诺，落败内容再次提交仍冲突，
353	// 库存五件全部由获胜承诺占用、归属保持不变。
354	func TestConcurrentReserveSameIDExactStockWinnerTakesAll(t *testing.T) {
355		const commitID = "cFull"
356		contentA := reserveContent{requestID: "r1", quantity: 5, expiry: expiryOK}
357		contentB := reserveContent{requestID: "r2", quantity: 5, expiry: expiryOK}
358	
359		const n = 12
360		for iter := 0; iter < 5; iter++ {
361			t.Run("iteration", func(t *testing.T) {
362				s := reserveContentionStore(t, 5)
363				calls := contentionCalls(commitID, "part1", contentA, contentB, n)
364				results := fanOutConcurrentReserve(s, calls)
365				assertReserveContentionSingleWinner(t, s, commitID, calls, results, 5, contentA, contentB)
366			})
367		}
368	}
